import{_ as t,o,c as n,a4 as a}from"./chunks/framework.BE47AOxC.js";const f=JSON.parse(`{"title":"Offres d'emploi","description":"Extension Offres d'emploi : ce que son manifeste déclare.","frontmatter":{"title":"Offres d'emploi","description":"Extension Offres d'emploi : ce que son manifeste déclare."},"headers":[],"relativePath":"extensions/offres-emploi.md","filePath":"extensions/offres-emploi.md"}`),r={name:"extensions/offres-emploi.md"};function s(i,e,d,c,l,u){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="offres-d-emploi" tabindex="-1">Offres d&#39;emploi <a class="header-anchor" href="#offres-d-emploi" aria-label="Permalink to &quot;Offres d&#39;emploi&quot;">​</a></h1><p>Les offres d&#39;emploi de la collectivité, avec deux formulaires publics de candidature — l&#39;un pour postuler à une offre précise, l&#39;autre en candidature spontanée — chacun notifiant automatiquement la bonne personne côté recrutement.</p><p><em>Présentation reprise de <a href="/teuthis-cms-distribution/documentation/notice/3-extensions-plugins#démarches-en-ligne-et-candidatures">la notice d&#39;utilisation</a>.</em></p><h2 id="en-bref" tabindex="-1">En bref <a class="header-anchor" href="#en-bref" aria-label="Permalink to &quot;En bref {#en-bref}&quot;">​</a></h2><ul><li><strong>Clé technique</strong> : <code>offres_emploi</code>, version <code>0.1.0</code>.</li><li><strong>Packs</strong> : <a href="/teuthis-cms-distribution/extensions/packs/secteur-public-fr">Secteur public FR</a>, <a href="/teuthis-cms-distribution/extensions/packs/agence">Agence</a>.</li><li><strong>Installée à l&#39;installation par le profil</strong> : <a href="/teuthis-cms-distribution/installer/?profil=collectivite">Collectivité</a>.</li></ul><h2 id="apports" tabindex="-1">Ce qu&#39;elle apporte <a class="header-anchor" href="#apports" aria-label="Permalink to &quot;Ce qu&#39;elle apporte {#apports}&quot;">​</a></h2><h3 id="types-de-contenu" tabindex="-1">Types de contenu <a class="header-anchor" href="#types-de-contenu" aria-label="Permalink to &quot;Types de contenu {#types-de-contenu}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nom</th><th>Clé</th><th>Archétype</th><th>Formulaire public</th></tr></thead><tbody><tr><td>Offre d&#39;emploi</td><td><code>offre_emploi</code></td><td><code>contenu_editorial_date</code></td><td>non</td></tr><tr><td>Candidature à une offre d&#39;emploi</td><td><code>candidature_offre_emploi</code></td><td><code>contenu_genere_par_formulaire</code></td><td>oui</td></tr><tr><td>Candidature spontanée</td><td><code>candidature_spontanee</code></td><td><code>contenu_genere_par_formulaire</code></td><td>oui</td></tr></tbody></table><h3 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages {#messages}&quot;">​</a></h3><p>Gabarits de notification : <code>offres_emploi.candidature.recue</code>, <code>offres_emploi.candidature.accusee</code>, <code>offres_emploi.spontanee.recue</code>, <code>offres_emploi.spontanee.accusee</code>.</p><h2 id="droits" tabindex="-1">Droits <a class="header-anchor" href="#droits" aria-label="Permalink to &quot;Droits {#droits}&quot;">​</a></h2><p><strong>Droits qu&#39;elle demande à l&#39;organisation</strong> : aucun.</p><h2 id="services-tiers" tabindex="-1">Services tiers et licences <a class="header-anchor" href="#services-tiers" aria-label="Permalink to &quot;Services tiers et licences {#services-tiers}&quot;">​</a></h2><p>Son manifeste ne déclare <strong>aucun service tiers</strong>.</p><h2 id="donnees-personnelles" tabindex="-1">Données personnelles <a class="header-anchor" href="#donnees-personnelles" aria-label="Permalink to &quot;Données personnelles {#donnees-personnelles}&quot;">​</a></h2><p><strong>Oui</strong>, d&#39;après son manifeste :</p><ul><li><strong>Candidature à une offre d&#39;emploi</strong> (<code>candidature_offre_emploi</code>) : type de contenu déclaré comme contenant des données personnelles. Champs marqués comme personnels : J&#39;accepte que ces informations soient traitées pour instruire ma candidature (<code>consentement</code>).</li><li><strong>Candidature spontanée</strong> (<code>candidature_spontanee</code>) : type de contenu déclaré comme contenant des données personnelles. Champs marqués comme personnels : Confirmez votre courriel (<code>courriel_confirmation</code>) ; J&#39;accepte que ces informations soient traitées pour instruire ma candidature (<code>consentement</code>).</li></ul><h2 id="notice" tabindex="-1">Dans la notice <a class="header-anchor" href="#notice" aria-label="Permalink to &quot;Dans la notice {#notice}&quot;">​</a></h2><p><a href="/teuthis-cms-distribution/documentation/notice/3-extensions-plugins#démarches-en-ligne-et-candidatures">La notice d&#39;utilisation présente cette extension</a> (section 3).</p>',19)])])}const m=t(r,[["render",s]]);export{f as __pageData,m as default};
